package com.Hecate.puppet.pixel;

import com.Hecate.puppet.volume.*;
import com.google.gson.Gson;
import com.jme3.math.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

final class PixelCoreTest {
    private VolumeDefinition box(){var d=new VolumeDefinition();d.setShape(VolumeDefinition.Shape.BOX);d.setDimensions(16,24,12);d.getBakedPixels().setEnabled(true);return d;}
    @Test void yawHasExactly20StepsAndOneColumnPer18Degrees(){var d=new BakedPixelDefinition();for(int i=-72;i<72;i++){var s=PixelViewSelector.select(d,i*PixelAtlas.YAW_DEGREES,0,40);assertEquals(Math.floorMod(i,PixelAtlas.YAW_VIEWS),s.yawStep());assertEquals(PixelAtlas.YAW_VIEWS+s.yawStep(),s.viewForRow(20));}assertEquals(0,PixelViewSelector.select(d,359,0,40).yawStep());}
    @Test void verticalTransitionsRevealWholeRows(){var d=new BakedPixelDefinition();int previous=0;for(float angle=18.5f;angle<=26.5f;angle+=.125f){var s=PixelViewSelector.select(d,0,angle,64);assertTrue(s.revealedRows()>=previous);for(int row=0;row<64;row++)assertEquals(row<s.revealedRows()?40:20,s.viewForRow(row));previous=s.revealedRows();}assertEquals(64,previous);}
    @Test void rasterizerCapturesIndependentLocalDepthAtEveryAngle(){var d=box();PixelAtlas a=PixelAtlasBaker.bake(d);int n=a.size();assertEquals((long)PixelAtlas.VIEWS*n*n*4,a.bytes());for(int view=0;view<PixelAtlas.VIEWS;view++){int count=0;for(int y=0;y<n;y++)for(int x=0;x<n;x++)if(a.occupied(view,x,y)){count++;Vector3f p=a.point(view,x,y);assertTrue(Math.abs(p.x)<=d.width()/2+.0001);assertTrue(Math.abs(p.y)<=d.height()/2+.0001);assertTrue(Math.abs(p.z)<=d.depth()/2+.0001);}assertTrue(count>30,"empty view "+view);}assertEquals(d.depth()/2,a.depth(20,n/2,n/2),.0001);a.dispose();}
    @Test void captureKeyIgnoresAnimationColorTextureAndMask(){var d=box();String k=PixelAtlasBaker.key(d);d.getBakedPixels().setTint(.1f,.2f,.3f);d.getStrip3D().layer(Strip3DDefinition.Surface.SIDE).setColorPath("different.png");d.getBakedPixels().setPriority(20);d.getBakedPixels().setTextureOrigin(9,4);assertEquals(k,PixelAtlasBaker.key(d));d.setDimensions(17,24,12);assertNotEquals(k,PixelAtlasBaker.key(d));}
    @Test void cacheSharesImmutableDataAndNeverExceedsBudget(){var d=box();long one=PixelAtlasBaker.estimateBytes(d);var cache=new PixelAtlasCache(one);try(var a=cache.acquire(d);var b=cache.acquire(d)){assertSame(a.atlas(),b.atlas());assertEquals(1,cache.builds());var changed=d.copy();changed.setDimensions(15,24,12);assertThrows(IllegalStateException.class,()->cache.acquire(changed));assertTrue(cache.bytes()<=one);}var changed=d.copy();changed.setDimensions(15,24,12);try(var c=cache.acquire(changed)){assertEquals(2,cache.builds());assertTrue(cache.bytes()<=one);}cache.clearUnused();assertEquals(0,cache.bytes());}
    @Test void handEditsAreCopyIsolatedSavedAndFlaggedAfterShapeChange(){var d=box();int n=PixelAtlasBaker.size(d);boolean[] mask=new boolean[n*n];mask[5]=true;d.getBakedPixels().setEdit(20,new BakedPixelDefinition.MaskEdit(n,mask,PixelAtlasBaker.key(d)));mask[5]=false;assertTrue(d.getBakedPixels().getEdit(20).mask()[5]);var gson=new Gson();var saved=gson.fromJson(gson.toJson(d),VolumeDefinition.class);assertTrue(saved.getBakedPixels().getEdit(20).mask()[5]);assertEquals(0,saved.getBakedPixels().staleEdits(PixelAtlasBaker.key(saved)));saved.setDimensions(20,24,12);assertEquals(1,saved.getBakedPixels().staleEdits(PixelAtlasBaker.key(saved)));assertEquals(0,d.getBakedPixels().staleEdits(PixelAtlasBaker.key(d)));}
    @Test void changingColorOrRepeatedLeasesDoesNotBakeAgain(){var d=box();var cache=new PixelAtlasCache(4*1024*1024);try(var hold=cache.acquire(d)){for(int i=0;i<10000;i++){d.getBakedPixels().setTint((i%255)/255f,1,1);PixelViewSelector.select(d.getBakedPixels(),i*.371f,(float)Math.sin(i)*60,hold.atlas().size());try(var reuse=cache.acquire(d)){assertSame(hold.atlas(),reuse.atlas());}}assertEquals(1,cache.builds());}cache.clearUnused();}
    @Test void oversizedPartsFailBeforeAllocatingInsteadOfChangingPixelScale(){var d=box();d.setDimensions(4096,4096,4096);assertThrows(IllegalArgumentException.class,()->PixelAtlasBaker.estimateBytes(d));}
}
